/* ══ state ═══════════════════════════════════════════════ */
const $ = id => document.getElementById(id);
/* Alles wat uit teams.json, localStorage of de sync komt en in innerHTML
   belandt gaat hierdoorheen. Eén helper, geen uitzonderingen. */
const esc = s => String(s).replace(/[&<>"']/g, c =>
  ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" })[c]);
const store = {
  get(k, d){ try{ const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; }catch{ return d; } },
  set(k, v){ try{ localStorage.setItem(k, JSON.stringify(v)); }catch{} },
  del(k){ try{ localStorage.removeItem(k); }catch{} },
};

const APP_VERSION = "0.03.3";   // bump bij elke release; historie in CHANGELOG.md

const DEFAULT_WHITELIST = DATA.leagues.map(l => l.id);   // klantwens: alles standaard aan
const defaults = () => ({ cooldown:6, pinned:4, kind:"mixed", womens:false,
                          whitelist:[...DEFAULT_WHITELIST], haptics:true });

/* rules6: het herhaalfilter telt nu élke trekking en staat standaard op 6.
   Oudere keys bewust niet overgenomen, zodat bestaande toestellen op de nieuwe
   defaults starten — en een league-filter dat ooit per ongeluk dichtstond
   (bv. de hele Premier League uit) daarmee opgeruimd is. */
let rules = Object.assign(defaults(), store.get("rules6", null) || {});
store.del("rules5");
if (!Array.isArray(rules.whitelist) || !rules.whitelist.length) rules.whitelist = [...DEFAULT_WHITELIST];

let duos = Object.assign({ a:"W/M", b:"J/J" }, store.get("duos", null) || {});
let matches = store.get("matches", null);          // persistent, alleen gekozen eindmatches
let rolls = [];                                    // sessie, vluchtig
let pending = store.get("pending", null);          // gekozen maar nog niet gespeeld

/* migratie van de oude `history`-key: alles met een score was een echte match,
   de rest waren rolls en die horen niet persistent te zijn. */
if (matches === null) {
  const old = store.get("history", []);
  matches = old.filter(h => h && (h.sa != null || h.chair)).map(h => ({
    ts:h.ts || Date.now(), aid:h.aid, bid:h.bid, an:h.an, bn:h.bn,
    ar:h.ar, br:h.br, stars:h.stars, delta:h.delta,
    sa:h.sa ?? 0, sb:h.sb ?? 0, chair:h.chair || "none",
  }));
  store.set("matches", matches);
}

/* migratie van de v1-webapp: gespeelde matches stonden in 'results',
   duo-namen in {wm,jj}, stoeltje als 'wm'/'jj'. */
function v1ToMatch(r){
  try{
    const wmA = r.wmPlays !== "b";
    const A = wmA ? r.a : r.b, B = wmA ? r.b : r.a;
    return { ts: r.playedAt || r.ts || Date.now(), aid:A.id, bid:B.id, an:A.name, bn:B.name,
             ar:A.rating, br:B.rating, stars:r.stars,
             delta: r.delta != null ? r.delta : Math.abs((A.rating||0)-(B.rating||0)),
             sa: wmA ? r.score.a : r.score.b, sb: wmA ? r.score.b : r.score.a,
             chair: r.chair === "wm" ? "a" : r.chair === "jj" ? "b" : "none" };
  }catch{ return null; }
}
(function migrateV1(){
  const oldR = store.get("results", null);
  if (Array.isArray(oldR) && oldR.length){
    const have = new Set(matches.map(m => m.ts));
    for (const m of oldR.map(v1ToMatch).filter(Boolean)) if (!have.has(m.ts)) matches.push(m);
    matches.sort((x, y) => (y.ts || 0) - (x.ts || 0));
    store.set("matches", matches);
    store.del("results");
  }
  const od = store.get("duos", null) || {};
  if (od.wm || od.jj){ duos = { a: od.wm || duos.a, b: od.jj || duos.b }; store.set("duos", duos); }
})();

/* sync: één JSON-blob GET/PUT (bijv. hosting/sync.php); leest ook de oude
   v1-vorm {duos, results}. Pull bij openen, push na elke mutatie. */
function syncPush(){
  const url = (store.get("syncUrl", "") || "").trim(); if (!url) return;
  fetch(url, { method:"PUT", headers:{ "Content-Type":"application/json" },
    body: JSON.stringify({ v:2, matches, duos, updated:new Date().toISOString() }) }).catch(()=>{});
}
async function syncPull(){
  const url = (store.get("syncUrl", "") || "").trim(); if (!url) return;
  try{
    const r = await fetch(url, { cache:"no-cache" });
    if (!r.ok) return;
    const doc = await r.json();
    let rm = null, rd = null;
    if (doc && Array.isArray(doc.matches)){ rm = doc.matches; rd = doc.duos; }
    else if (doc && Array.isArray(doc.results)){
      rm = doc.results.map(v1ToMatch).filter(Boolean);
      rd = doc.duos && doc.duos.wm ? { a:doc.duos.wm, b:doc.duos.jj } : doc.duos;
    }
    if (!rm) return;
    if (rm.length >= matches.length){
      matches = rm; store.set("matches", matches);
      if (rd && rd.a){ duos = rd; store.set("duos", duos); }
      renderStand(); renderFinal();
    } else syncPush();
  }catch{ /* offline of endpoint down: lokaal blijft leidend */ }
}

const saveRules = () => store.set("rules6", rules);
const saveMatches = () => store.set("matches", matches = matches.slice(0, 200));
const savePending = () => pending ? store.set("pending", pending) : store.del("pending");
const saveDuos = () => store.set("duos", duos);

/* ══ engine, ongewijzigd behalve de history-bron ══════════ */
function poolFilter(t){
  if (t.squadRating == null) return false;
  if (t.womens && !rules.womens) return false;
  if (rules.kind === "clubs" && t.kind !== "club") return false;
  if (rules.kind === "nats" && t.kind !== "national") return false;
  if (t.kind === "club" && !rules.whitelist.includes(t.leagueId)) return false;
  if (rules.pinned != null && t.starRating !== rules.pinned) return false;
  return true;
}
/* Gelijk aantal sterren is dé eerlijkheidsregel; de squad rating staat op de
   kaart maar filtert niet. Kies gewogen een ster-bucket, dan twee teams. */
function attempt(pool){
  const buckets = new Map();
  for (const t of pool){
    const key = t.kind + "|" + t.starRating;
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(t);
  }
  const viable = [...buckets.values()].filter(ts => ts.length >= 2);
  if (!viable.length) return null;
  const total = viable.reduce((s, ts) => s + ts.length, 0);
  let pick = Math.floor(Math.random() * total);
  let teams = viable[0];
  for (const ts of viable){ if (pick < ts.length){ teams = ts; break; } pick -= ts.length; }
  const i = Math.floor(Math.random() * teams.length);
  let j = Math.floor(Math.random() * (teams.length - 1));
  if (j >= i) j++;
  return Math.random() < 0.5 ? [teams[i], teams[j]] : [teams[j], teams[i]];
}
/* Het herhaalfilter kijkt naar élke recente trekking: de rolls van vanavond,
   de gekozen eindmatch en de gespeelde matches. Nieuwste eerst, en een paar dat
   zowel gerold als gespeeld is telt één keer — anders vreet het twee plekken
   in het venster. */
function recentDraws(){
  const seen = new Set(), out = [];
  const all = [...rolls, ...matches, ...(pending ? [pending] : [])]
    .filter(d => d && d.aid && d.bid)
    .sort((x, y) => (y.ts || 0) - (x.ts || 0));
  for (const d of all){
    const key = [d.aid, d.bid].sort().join("|");
    if (seen.has(key)) continue;
    seen.add(key); out.push([d.aid, d.bid]);
  }
  return out;
}
function drawPair(){
  const base = DATA.teams.filter(poolFilter);
  if (!base.length) return { error:"De pool is leeg met deze filters." };
  const recent = recentDraws();
  const want = Math.min(rules.cooldown, recent.length);
  // Versoepel zo min mogelijk: krimp het venster tot er weer een paar past.
  for (let window = want; window >= 0; window--){
    const block = new Set(recent.slice(0, window).flat());
    const pair = attempt(block.size ? base.filter(t => !block.has(t.id)) : base);
    if (!pair) continue;
    const relax = window === want ? []
      : [window ? `herhaalfilter beperkt tot ${window} draw${window === 1 ? "" : "s"}`
                : "herhaalfilter losgelaten"];
    return { a:pair[0], b:pair[1],
             delta:Math.abs(pair[0].squadRating - pair[1].squadRating), relax };
  }
  const star = rules.pinned != null ? rules.pinned.toLocaleString("nl") + " sterren " : "";
  return { error:"Geen eerlijk paar op " + star + "met deze filters." };
}

/* ══ kaart-rendering ═════════════════════════════════════ */
const STAR = "M12 2l2.9 6.3 6.9.8-5.1 4.7 1.4 6.8L12 17.2 5.9 20.6l1.4-6.8L2.2 9.1l6.9-.8z";
const starSvg = cls => `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${STAR}"/></svg>`;

/* Alleen echte clublogos. Geen initialen-badge, geen gegenereerd merkteken.
   Zolang het logo laadt of als het ontbreekt staat er een neutrale plaat;
   de clubnaam in de naambalk doet het identificeren. */
function crestNode(t){
  const wrap = document.createElement("div"); wrap.className = "crest";
  const plate = document.createElement("span"); plate.className = "plate";
  wrap.appendChild(plate);
  if (!t.crestURL) return wrap;
  const img = document.createElement("img");
  img.alt = ""; img.loading = "eager"; img.decoding = "async";
  img.addEventListener("load", () => { img.classList.add("on"); wrap.classList.add("ok"); });
  img.addEventListener("error", () => img.remove());
  img.src = t.crestURL;
  wrap.appendChild(img);
  return wrap;
}
function starsHTML(t, on){
  return [0,1,2,3,4].map(i => {
    const f = t.starRating - i >= 1 ? 1 : (t.starRating - i >= .5 ? .5 : 0);
    return `<span class="st${i < on ? " on" : ""}">${starSvg("dim")}<span class="lit" style="width:${f*100}%;display:${f?"block":"none"}">${starSvg("")}</span></span>`;
  }).join("");
}
const leagueLabel = t => t.kind === "national"
  ? (t.womens ? "Landenteam · vrouwen" : "Landenteam")
  : (t.leagueName || "Onbekende league");

/* Het tier-materiaal komt uit de sterrating. Beide kaarten in een loting
   hebben dezelfde sterrating, dus altijd hetzelfde materiaal. */
function tierClass(stars){
  if (stars >= 4.5) return "t-elite";
  if (stars >= 3.5) return "t-gold";
  if (stars >= 2.5) return "t-silver";
  if (stars >= 1.5) return "t-bronze";
  return "t-base";
}
function setTier(stars){
  const c = $("cards");
  c.classList.remove("t-elite","t-gold","t-silver","t-bronze","t-base");
  c.classList.add(tierClass(stars));
}

function skeleton(card, who){
  card.classList.remove("settled","ghost","skel");
  card.innerHTML =
    `<span class="duoname">${esc(who)}</span>
     <div class="chead">
       <span class="rating hide">0</span>
       <span class="stars" role="img" aria-label="rating nog onbekend">${starsHTML({starRating:0}, 0)}</span>
     </div>
     <div class="identity"><div class="layer"></div></div>
     <div class="cfoot">
       <div class="tname"><span>&nbsp;</span></div>
       <div class="league">· · ·</div>
     </div>`;
}
function ghost(card, who, skel){
  card.className = "card " + (card.classList.contains("a") ? "a" : "b") + " ghost in" + (skel ? " skel" : "");
  card.innerHTML =
    `<span class="duoname">${esc(who)}</span>
     <div class="chead"><span class="ghost-line" style="width:34px;height:24px"></span>
       <span class="ghost-line" style="width:64px;height:11px"></span></div>
     <div class="identity" style="display:grid;place-items:center"><div class="ghost-crest"></div></div>
     <div class="cfoot"><div class="ghost-line" style="width:74%"></div>
       <div class="ghost-line" style="width:44%;height:8px;margin-top:5px"></div></div>`;
}

/* Snel cyclen = harde knip, ook bij de landing. Eén laag, geen crossfade. */
function swapTeam(card, t, reel){
  const layer = card.querySelector(".layer");
  layer.replaceChildren(crestNode(t));
  const nm = card.querySelector(".tname span");
  if (nm) nm.textContent = t.name;
  if (reel){ layer.classList.remove("reel"); void layer.offsetWidth; layer.classList.add("reel"); }
}
function settleCard(card, t){
  swapTeam(card, t, false);
  card.querySelector(".league").textContent = leagueLabel(t);
  const stars = card.querySelector(".stars");
  stars.innerHTML = starsHTML(t, 0);
  stars.setAttribute("aria-label", t.starRating.toLocaleString("nl") + " van 5 sterren");
  card.classList.add("settled");
}

/* ══ ceremonie ═══════════════════════════════════════════ */
const reduce = matchMedia("(prefers-reduced-motion: reduce)");
const wait = ms => new Promise(r => setTimeout(r, ms));
let running = false, skip = false, gen = 0, settled = null;

function buzz(ms){
  if (!rules.haptics) return;
  try{ navigator.vibrate && navigator.vibrate(ms); }catch{}
}
function announce(r){
  $("announce").textContent =
    `${r.a.name}, ${r.a.starRating.toLocaleString("nl")} sterren, rating ${r.a.squadRating}, ` +
    `tegen ${r.b.name}, ${r.b.starRating.toLocaleString("nl")} sterren, rating ${r.b.squadRating}. ` +
    `Verschil ${r.delta}, ${verdictWord(r.delta)}.`;
}
const verdictWord = d => d <= 1 ? "gelijkwaardig" : d <= 3 ? "net aan" : "scheef";

function countUp(g, r, A, B){
  const t0 = performance.now(), dur = 600;
  const from = { a:Math.max(0, r.a.squadRating - 15), b:Math.max(0, r.b.squadRating - 15) };
  const ra = A.querySelector(".rating"), rb = B.querySelector(".rating");
  ra.setAttribute("aria-hidden","true"); rb.setAttribute("aria-hidden","true");
  return new Promise(done => {
    const tick = () => {
      if (g !== gen) return done();
      const p = Math.min(1, (performance.now() - t0) / dur);
      const e = 1 - Math.pow(2, -10 * p);                       // easeOutExpo
      ra.textContent = Math.round(from.a + (r.a.squadRating - from.a) * e);
      rb.textContent = Math.round(from.b + (r.b.squadRating - from.b) * e);
      p < 1 ? requestAnimationFrame(tick) : done();
    };
    requestAnimationFrame(tick);
  });
}

function showFair(r){
  settled = r;
  const lo0 = Math.min(r.a.squadRating, r.b.squadRating) - 4;
  const hi0 = Math.max(r.a.squadRating, r.b.squadRating) + 4;
  let lo = lo0, hi = hi0;
  if (hi - lo < 10){ const pad = (10 - (hi - lo)) / 2; lo -= pad; hi += pad; }
  const pos = v => ((v - lo) / (hi - lo)) * 100;
  const pa = pos(r.a.squadRating), pb = pos(r.b.squadRating);
  const same = r.delta === 0;
  $("mA").style.left = pa + "%";
  $("mB").style.left = pb + "%";
  $("mB").hidden = same;
  // Bij Δ0 vallen de markers samen: één marker, half blauw half amber, één label.
  // Bij Δ0 vallen de markers samen. Eén marker, geen duokleur:
  // duokleuren bestaan alleen in de Stand.
  $("mA").style.boxShadow = same
    ? "0 0 0 3px var(--accent), 0 2px 6px rgba(0,0,0,.6)"
    : "";
  $("mAv").textContent = r.a.squadRating;
  $("mBv").textContent = same ? "" : r.b.squadRating;
  $("fgap").style.left = Math.min(pa, pb) + "%";
  $("fgap").style.width = Math.abs(pb - pa) + "%";
  $("fWord").textContent = verdictWord(r.delta);
  $("fDelta").textContent = "verschil " + r.delta;
  $("fRelax").hidden = !r.relax.length;
  $("fRelax").textContent = r.relax.join(", ");
  $("fair").classList.add("show");
  $("pickRow").hidden = false;
  $("pickBtn").textContent = "Kies als eindmatch";
  $("pickBtn").disabled = false;
}

function jump(r){
  setTier(r.a.starRating);
  for (const [card, t, who] of [[$("cardA"), r.a, duos.a], [$("cardB"), r.b, duos.b]]){
    card.classList.add("in"); card.classList.remove("out","settled");
    skeleton(card, who);
    card.querySelector(".layer").replaceChildren(crestNode(t));
    card.querySelector(".tname span").textContent = t.name;
    card.querySelector(".league").textContent = leagueLabel(t);
    const stars = card.querySelector(".stars");
    stars.innerHTML = starsHTML(t, 5);
    stars.setAttribute("aria-label", t.starRating.toLocaleString("nl") + " van 5 sterren");
    const rt = card.querySelector(".rating");
    rt.textContent = t.squadRating; rt.classList.remove("hide"); rt.setAttribute("aria-hidden","true");
  }
  $("vs").classList.add("show");
  showFair(r);
  announce(r);
  setSpinning(false);
  running = false;
}

function setSpinning(on){
  const b = $("draw");
  b.textContent = on ? "Overslaan" : "Draw";
  b.classList.toggle("spinning", on);
  $("skipHint").textContent = on ? "tik om over te slaan" : "";
}

async function ceremony(r, pool){
  const g = ++gen;
  running = true; skip = false;
  const A = $("cardA"), B = $("cardB");
  $("stageNote").hidden = true;
  setTier(r.a.starRating);
  $("vs").classList.remove("show");
  $("fair").classList.remove("show");
  $("pickRow").hidden = true;
  setSpinning(true);

  const wasIn = A.classList.contains("in") && !A.classList.contains("ghost");
  if (wasIn){
    A.classList.add("out"); B.classList.add("out");
    await wait(190); if (g !== gen) return;
    A.classList.remove("in","out","settled"); B.classList.remove("in","out","settled");
    void A.offsetHeight;
  } else {
    A.classList.remove("ghost","skel","in"); B.classList.remove("ghost","skel","in");
  }

  skeleton(A, duos.a); skeleton(B, duos.b);
  const rand = () => pool[Math.floor(Math.random() * pool.length)] || r.a;
  const bail = () => { if (skip || g !== gen){ if (g === gen) jump(r); return true; } return false; };

  if (reduce.matches){
    A.classList.add("in"); B.classList.add("in");
    await wait(20); if (bail()) return;
    jump(r);
    buzz(18);
    return;
  }

  swapTeam(A, rand(), true); swapTeam(B, rand(), true);
  A.classList.add("in"); B.classList.add("in");
  await wait(180); if (bail()) return;

  // spin: harde knip op 64ms
  for (let t = 0; t < 520; t += 60){
    swapTeam(A, rand(), true); swapTeam(B, rand(), true);
    await wait(60); if (bail()) return;
  }
  // deceleratie: 7 stappen, 60ms -> 240ms, easeOutQuart. De reel loopt uit.
  // Totale ceremonie ~2.9s. Langer dan dat gaat irriteren als je doorrolt.
  const STEPS = 7;
  for (let i = 1; i <= STEPS; i++){
    const e = 1 - Math.pow(1 - i / STEPS, 4);
    swapTeam(A, rand(), true); swapTeam(B, rand(), true);
    await wait(60 + (240 - 60) * e); if (bail()) return;
  }

  settleCard(A, r.a);
  await wait(300); if (bail()) return;                 // de stilte. niet inkorten.
  settleCard(B, r.b);
  await wait(70); if (bail()) return;

  A.querySelector(".rating").classList.remove("hide");
  B.querySelector(".rating").classList.remove("hide");
  countUp(g, r, A, B);
  const sa = A.querySelectorAll(".st"), sb = B.querySelectorAll(".st");
  for (let i = 0; i < 5; i++){
    sa[i].classList.add("on");
    setTimeout(() => sb[i] && sb[i].classList.add("on"), 70);
    await wait(45); if (bail()) return;
  }
  buzz(18);
  $("vs").classList.add("show");
  await wait(120); if (bail()) return;
  showFair(r);
  announce(r);
  setSpinning(false);
  running = false;
}

/* ══ draw ════════════════════════════════════════════════ */
function doDraw(){
  if (running){ skip = true; return; }
  const r = drawPair();
  if (r.error){
    gen++;
    $("fair").classList.remove("show");
    $("pickRow").hidden = true;
    const A = $("cardA"), B = $("cardB");
    ghost(A, duos.a); ghost(B, duos.b);
    $("vs").classList.remove("show");
    $("stageNote").hidden = false;
    $("stageNote").innerHTML =
      `<b style="color:var(--danger)">${esc(r.error)}</b><br>` +
      `<span style="display:inline-flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:12px">
         <button class="pick" id="fixStar">Elke ster oké</button>
         <button class="pick" id="fixLeagues">Leagues aanzetten</button>
       </span>`;
    $("fixStar").onclick = () => { rules.pinned = null; saveRules(); syncFilters(); doDraw(); };
    $("fixLeagues").onclick = () => { openSheet("sheetStand", true); openSheet("sheetFilters"); $("lgToggle").click(); };
    return;
  }
  rolls.unshift({ ts:Date.now(), aid:r.a.id, bid:r.b.id, an:r.a.name, bn:r.b.name,
                  ar:r.a.squadRating, br:r.b.squadRating, stars:r.a.starRating, delta:r.delta });
  rolls = rolls.slice(0, 20);
  renderStand();
  ceremony(r, DATA.teams.filter(poolFilter));
}
$("draw").addEventListener("click", doDraw);
$("stage").addEventListener("click", e => {
  if (running && !e.target.closest("button")) skip = true;
});

/* ══ eindmatch ═══════════════════════════════════════════ */
$("pickBtn").addEventListener("click", () => {
  if (!settled) return;
  const r = settled;
  pending = { ts:Date.now(), aid:r.a.id, bid:r.b.id, an:r.a.name, bn:r.b.name,
              ar:r.a.squadRating, br:r.b.squadRating, stars:r.a.starRating, delta:r.delta,
              sa:0, sb:0, chair:null };
  savePending(); renderFinal();
  $("pickRow").hidden = true;
  toast("Eindmatch gekozen");
});
$("dropFinal").addEventListener("click", () => { pending = null; savePending(); renderFinal(); });
$("openScore").addEventListener("click", () => {
  document.body.classList.add("scoring");
  $("scoreBlock").hidden = false; $("openScore").hidden = true; $("fMid").hidden = true;
  $("sA").focus();
});
document.querySelectorAll("[data-s]").forEach(b => b.addEventListener("click", () => {
  const [id, d] = b.dataset.s.split(":");
  const el = $(id);
  el.value = Math.max(0, Math.min(99, (Number(el.value) || 0) + Number(d)));
}));
$("saveScore").addEventListener("click", () => {
  if (!pending) return;
  if (!pending.chair){
    $("chair").classList.add("err"); $("chairErr").hidden = false;
    $("chairBtns").scrollIntoView({ block:"nearest", behavior:"smooth" });
    return;
  }
  pending.sa = Math.max(0, Math.min(99, Number($("sA").value) || 0));
  pending.sb = Math.max(0, Math.min(99, Number($("sB").value) || 0));
  matches.unshift(pending);
  saveMatches(); syncPush();
  pending = null; savePending();
  renderFinal(); renderStand();
  buzz([12,60,12]);
  toast("Score opgeslagen");
});

function renderFinal(){
  document.body.classList.remove("scoring");
  const f = $("final");
  f.hidden = !pending;
  $("pendingDot").hidden = !pending;
  if (!pending) return;
  $("fWhoA").textContent = duos.a; $("fClubA").textContent = pending.an;
  $("fWhoB").textContent = duos.b; $("fClubB").textContent = pending.bn;
  $("scoreBlock").hidden = true; $("openScore").hidden = false; $("fMid").hidden = false;
  $("chair").classList.remove("err"); $("chairErr").hidden = true;
  $("sA").value = pending.sa; $("sB").value = pending.sb;
  const wrap = $("chairBtns"); wrap.innerHTML = "";
  for (const [key, label] of [["a", duos.a], ["b", duos.b], ["none", "Niemand"]]){
    const b = document.createElement("button");
    b.textContent = label;
    b.setAttribute("aria-pressed", String(pending.chair === key));
    b.onclick = () => { pending.chair = key; savePending();
      $("chair").classList.remove("err"); $("chairErr").hidden = true; renderChair(); };
    wrap.appendChild(b);
  }
}
function renderChair(){
  const btns = $("chairBtns").children;
  const keys = ["a","b","none"];
  for (let i = 0; i < btns.length; i++) btns[i].setAttribute("aria-pressed", String(pending && pending.chair === keys[i]));
}

/* ══ filters ═════════════════════════════════════════════ */
function seg(host, items, active, pick){
  host.innerHTML = "";
  for (const [val, label] of items){
    const b = document.createElement("button");
    b.textContent = label;
    b.setAttribute("aria-pressed", String(active === val));
    b.onclick = () => pick(val);
    host.appendChild(b);
  }
}
function syncFilters(){
  seg($("kindSeg"), [["clubs","Clubs"],["nats","Landen"],["mixed","Mix"]], rules.kind,
      v => { rules.kind = v; saveRules(); syncFilters(); renderLeagues(); });
  $("womens").checked = rules.womens;
  const mode = rules.pinned == null ? "any" : "fixed";
  seg($("starSeg"), [["any","Verras ons"],["fixed","Vaste ster"]], mode, v => {
    rules.pinned = v === "any" ? null : Number($("starRange").value);
    saveRules(); syncFilters();
  });
  $("starSlider").hidden = mode !== "fixed";
  if (mode === "fixed") $("starRange").value = rules.pinned;
  $("starOut").textContent = Number($("starRange").value).toLocaleString("nl") + " sterren";
  $("vCool").textContent = rules.cooldown;
  const visLeagues = DATA.leagues.filter(l => !l.womens || rules.womens);
  $("lgCount").textContent = visLeagues.filter(l => rules.whitelist.includes(l.id)).length + " van " + visLeagues.length + " aan";
  $("poolN").textContent = DATA.teams.filter(poolFilter).length;
}
$("womens").addEventListener("change", e => {
  rules.womens = e.target.checked; saveRules(); renderLeagues(); syncFilters();
});
$("starRange").addEventListener("input", e => {
  rules.pinned = Number(e.target.value); saveRules(); syncFilters();
});
document.querySelectorAll("[data-step]").forEach(b => b.addEventListener("click", () => {
  const [, d] = b.dataset.step.split(":");
  rules.cooldown = Math.max(0, Math.min(20, rules.cooldown + Number(d)));
  saveRules(); syncFilters();
}));
$("resetRules").addEventListener("click", () => {
  rules = defaults(); saveRules(); syncFilters(); renderLeagues(); toast("Filters teruggezet");
});

const TIER = l => l.defaultWhitelist ? "Top" : (["eng","ger","esp","ita","fra","ned","por","bel","tur","sco","sui","den","nor","swe","pol","rou"].includes(l.id.split(".")[0]) ? "Europa" : "Wereld");
$("lgToggle").addEventListener("click", () => {
  const open = $("lgToggle").getAttribute("aria-expanded") === "true";
  $("lgToggle").setAttribute("aria-expanded", String(!open));
  $("lgList").hidden = open;
});
function renderLeagues(){
  const host = $("lgList"); host.innerHTML = "";
  const visible = DATA.leagues.filter(l => rules.womens || !l.womens);
  const tiers = { Top:[], Europa:[], Wereld:[] };
  for (const l of visible) tiers[TIER(l)].push(l);
  for (const name of ["Top","Europa","Wereld"]){
    const list = tiers[name].sort((a,b) => a.name.localeCompare(b.name));
    if (!list.length) continue;
    const box = document.createElement("div"); box.className = "lgtier";
    const head = document.createElement("div"); head.className = "head";
    const lbl = document.createElement("span"); lbl.className = "lbl"; lbl.textContent = name;
    const all = document.createElement("button");
    all.className = "btn"; all.style.minHeight = "44px"; all.style.padding = "0 14px";
    const on = list.every(l => rules.whitelist.includes(l.id));
    all.textContent = on ? "Alles uit" : "Alles aan";
    all.onclick = () => {
      const ids = list.map(l => l.id);
      rules.whitelist = on ? rules.whitelist.filter(x => !ids.includes(x))
                           : [...new Set([...rules.whitelist, ...ids])];
      saveRules(); renderLeagues(); syncFilters();
    };
    head.append(lbl, all); box.appendChild(head);
    for (const l of list){
      const row = document.createElement("div"); row.className = "lgrow";
      const nm = document.createElement("span"); nm.className = "nm";
      nm.innerHTML = `<b></b><span>${esc(l.countryCode)}</span>`;
      nm.querySelector("b").textContent = l.name;
      const sw = document.createElement("label"); sw.className = "sw";
      const cb = document.createElement("input"); cb.type = "checkbox";
      cb.checked = rules.whitelist.includes(l.id);
      cb.setAttribute("aria-label", l.name);
      cb.onchange = () => {
        rules.whitelist = cb.checked ? [...rules.whitelist, l.id] : rules.whitelist.filter(x => x !== l.id);
        saveRules(); syncFilters();
        const head = box.querySelector(".head .btn");
        const allOn = list.every(x => rules.whitelist.includes(x.id));
        head.textContent = allOn ? "Alles uit" : "Alles aan";
      };
      sw.append(cb, document.createElement("i"));
      row.append(nm, sw); box.appendChild(row);
    }
    host.appendChild(box);
  }
}

/* ══ stand ═══════════════════════════════════════════════ */
function renderStand(){
  $("h2hNA").textContent = duos.a; $("h2hNB").textContent = duos.b;
  const played = matches;
  let wa = 0, wb = 0, dr = 0, ga = 0, gb = 0, csa = 0, csb = 0;
  for (const m of played){
    ga += m.sa; gb += m.sb;
    if (m.sb === 0) csa++;
    if (m.sa === 0) csb++;
    if (m.sa > m.sb) wa++; else if (m.sb > m.sa) wb++; else dr++;
  }
  $("h2hA").textContent = wa; $("h2hB").textContent = wb;

  const form = $("form"); form.innerHTML = "";
  for (const m of played.slice(0, 8).reverse()){
    const i = document.createElement("i");
    i.style.background = m.sa > m.sb ? "var(--duo-a)" : m.sb > m.sa ? "var(--duo-b)" : "var(--edge)";
    form.appendChild(i);
  }

  const gpm = played.length ? ((ga + gb) / played.length).toFixed(1).replace(".", ",") : "0,0";
  $("kpis").innerHTML = [
    [`${ga - gb > 0 ? "+" : ""}${ga - gb}`, "doelsaldo " + duos.a],
    [gpm, "goals per match"],
    [String(dr), dr === 1 ? "gelijkspel" : "gelijkspelen"],
  ].map(([v, k]) => `<div class="kpi"><div class="v">${esc(v)}</div><div class="k">${esc(k)}</div></div>`).join("");

  const bars = $("bars"); bars.innerHTML = "";
  const last = played.slice(0, 10).reverse();
  const max = Math.max(1, ...last.map(m => Math.abs(m.sa - m.sb)));
  for (const m of last){
    const i = document.createElement("i");
    const d = m.sa - m.sb;
    i.style.height = (8 + (Math.abs(d) / max) * 62) + "px";
    i.style.background = d > 0 ? "var(--duo-a)" : d < 0 ? "var(--duo-b)" : "var(--edge)";
    bars.appendChild(i);
  }
  if (!last.length) bars.innerHTML = '<span class="empty">Nog geen marges om te tekenen.</span>';
  $("chartLegend").innerHTML =
    `<span><b style="background:var(--duo-a)"></b>${esc(duos.a)}</span>
     <span><b style="background:var(--duo-b)"></b>${esc(duos.b)}</span>`;

  const fav = t => { const c = {}; for (const m of played){ c[m[t]] = (c[m[t]] || 0) + 1; }
    const k = Object.keys(c).sort((x,y) => c[y] - c[x])[0];
    return k ? `${k} (${c[k]}×)` : "nog geen"; };
  const chairStats = () => {
    const on = played.filter(m => m.chair === "a" || m.chair === "b");
    if (!on.length) return "nog geen";
    const lost = on.filter(m => (m.chair === "a" && m.sb > m.sa) || (m.chair === "b" && m.sa > m.sb)).length;
    return `${Math.round((1 - lost / on.length) * 100)}% winst vanaf 't stoeltje`;
  };
  $("defs").innerHTML = [
    ["Gespeeld", played.length + (played.length === 1 ? " match" : " matches")],
    ["Clean sheets", `${csa} · ${csb}`],
    [`Favo club ${duos.a}`, fav("an")],
    [`Favo club ${duos.b}`, fav("bn")],
    ["Sterrating", played.length ? fav("stars").replace(/^([\d.,]+)/, (m) => m.replace(".", ",") + " ster") : "nog geen"],
    ["'t Stoeltje", chairStats()],
  ].map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join("");

  const pl = $("playedList");
  pl.innerHTML = played.length ? played.slice(0, 12).map((m, i) =>
    `<div class="mrow">
       <span class="t">${esc(m.an)}</span>
       <span class="s">${esc(m.sa)}–${esc(m.sb)}</span>
       <span class="t r">${esc(m.bn)}</span>
       <button class="x" data-del="${i}" aria-label="Match verwijderen">✕</button>
     </div>`).join("")
    : '<p class="empty">Nog geen gespeelde matches. Kies een loting als eindmatch en vul de score in.</p>';

  $("rollLabel").textContent = rolls.length
    ? `ook gerold vanavond (${rolls.length})` : "nog niks gerold vanavond";
  $("rollList").innerHTML = rolls.length ? rolls.map(r =>
    `<div class="mrow">
       <span class="t">${esc(r.an)}</span>
       <span class="s">${esc(r.ar)}–${esc(r.br)}</span>
       <span class="t r">${esc(r.bn)}</span>
       <span class="s" style="color:var(--tx-3)">Δ${esc(r.delta)}</span>
     </div>`).join("") : '<p class="empty">Rolls van vanavond worden niet bewaard en tellen niet mee voor het herhaalfilter.</p>';
}
$("playedList").addEventListener("click", e => {
  const b = e.target.closest("[data-del]");
  if (!b) return;
  matches.splice(Number(b.dataset.del), 1);
  saveMatches(); syncPush(); renderStand();
});
$("rollToggle").addEventListener("click", () => {
  const open = $("rollToggle").getAttribute("aria-expanded") === "true";
  $("rollToggle").setAttribute("aria-expanded", String(!open));
  $("rollList").hidden = open;
});

